{
  "name": "EV Eco-Navigator Pro",
  "description": "A high-performance EV dashboard that optimizes routes based on elevation, traffic, and regenerative braking to ensure arrival with optimal battery life.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface RouteOption {
  id: string;
  name: string;
  distanceKm: number;
  durationMin: number;
  elevationGainM: number;
  elevationLossM: number;
  trafficLevel: 'Low' | 'Moderate' | 'High';
  estimatedBatteryConsumption: number; // in percentage
  isOptimal: boolean;
  reasoning: string;
}

export interface EVState {
  currentSpeed: number;
  recommendedSpeed: number;
  batteryPercent: number;
  rangeKm: number;
  efficiencyWhKm: number;
  instantConsumptionKw: number;
}

export interface NavigationTarget {
  destination: string;
  distanceKm: number;
  eta: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { RouteOption } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function optimizeRoute(destination: string, currentBattery: number): Promise<RouteOption[]> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze possible routes to ${destination}. Current EV battery is ${currentBattery}%. 
      Consider elevation profiles (uphills/downhills), traffic conditions, and regenerative braking.
      Provide 3 route options: 
      1. Fastest Route
      2. Most Energy Efficient (using downhills for regen, avoiding steep uphills)
      3. Balanced (good mix of speed and efficiency).
      Ensure one route is flagged as 'isOptimal' based on the goal: arrive with >= 10% battery.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              distanceKm: { type: Type.NUMBER },
              durationMin: { type: Type.NUMBER },
              elevationGainM: { type: Type.NUMBER },
              elevationLossM: { type: Type.NUMBER },
              trafficLevel: { type: Type.STRING },
              estimatedBatteryConsumption: { type: Type.NUMBER },
              isOptimal: { type: Type.BOOLEAN },
              reasoning: { type: Type.STRING }
            },
            required: ["id", "name", "distanceKm", "durationMin", "elevationGainM", "elevationLossM", "trafficLevel", "estimatedBatteryConsumption", "isOptimal", "reasoning"]
          }
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Gemini Error:", error);
    // Fallback Mock Data if API fails or key is missing
    return [
      {
        id: "1",
        name: "Valley Expressway",
        distanceKm: 42,
        durationMin: 35,
        elevationGainM: 50,
        elevationLossM: 200,
        trafficLevel: 'Low',
        estimatedBatteryConsumption: 12,
        isOptimal: true,
        reasoning: "Utilizes significant downhill sections for energy recovery. Low traffic allows steady efficient speed."
      },
      {
        id: "2",
        name: "Mountain Pass",
        distanceKm: 38,
        durationMin: 45,
        elevationGainM: 400,
        elevationLossM: 100,
        trafficLevel: 'Moderate',
        estimatedBatteryConsumption: 25,
        isOptimal: false,
        reasoning: "High elevation gain causes rapid battery depletion. Not recommended for low battery states."
      }
    ];
  }
}

export async function getEfficiencyTip(speed: number, battery: number): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Current speed is ${speed} km/h, battery is ${battery}%. Give a short (max 12 words) efficiency tip for the EV driver.`,
    });
    return response.text.trim();
  } catch {
    return "Maintain 85 km/h for optimal range in current conditions.";
  }
}

import React from 'react';

interface Props {
  currentSpeed: number;
  recommendedSpeed: number;
  consumption: number;
}

const Speedometer: React.FC<Props> = ({ currentSpeed, recommendedSpeed, consumption }) => {
  const percentage = Math.min((currentSpeed / 160) * 100, 100);
  const recPercentage = Math.min((recommendedSpeed / 160) * 100, 100);

  // Power/Regen meter calculation
  // -10kW (Regen) to +50kW (Heavy Acceleration)
  const consumptionNormal = Math.max(-10, Math.min(50, consumption));
  const consPct = ((consumptionNormal + 10) / 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center p-6 glass-panel rounded-3xl relative overflow-hidden h-full">
      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-cyan-400 to-green-500 opacity-30"></div>

      {/* Speed Display */}
      <div className="relative w-64 h-64 flex items-center justify-center">
        {/* Main Gauge Ring */}
        <svg className="w-full h-full transform -rotate-90">
          <circle
            cx="128"
            cy="128"
            r="110"
            stroke="rgba(255,255,255,0.05)"
            strokeWidth="8"
            fill="transparent"
            strokeDasharray="691"
          />
          <circle
            cx="128"
            cy="128"
            r="110"
            stroke={currentSpeed > recommendedSpeed + 10 ? '#ef4444' : '#06b6d4'}
            strokeWidth="12"
            fill="transparent"
            strokeDasharray="691"
            strokeDashoffset={691 - (691 * (percentage * 0.75)) / 100}
            className="transition-all duration-500 ease-out"
            strokeLinecap="round"
          />
          {/* Recommended Speed Tick */}
          <line
            x1="128"
            y1="18"
            x2="128"
            y2="38"
            stroke="#22c55e"
            strokeWidth="4"
            transform={`rotate(${(recPercentage * 0.75 * 3.6)}, 128, 128)`}
            className="transition-all duration-1000"
          />
        </svg>

        <div className="absolute flex flex-col items-center">
          <span className="text-7xl font-orbitron font-bold glow-cyan">{Math.round(currentSpeed)}</span>
          <span className="text-sm text-gray-400 font-medium tracking-widest uppercase">km/h</span>
        </div>
      </div>

      {/* Recommended Info */}
      <div className="mt-8 grid grid-cols-2 gap-8 w-full">
        <div className="flex flex-col items-center border-r border-gray-800">
          <span className="text-xs text-gray-500 uppercase font-bold tracking-tighter">Target Speed</span>
          <span className="text-2xl font-orbitron text-green-400">{recommendedSpeed}</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-xs text-gray-500 uppercase font-bold tracking-tighter">ECO Mode</span>
          <span className="text-2xl font-orbitron text-cyan-400">Active</span>
        </div>
      </div>

      {/* Consumption / Regen Meter */}
      <div className="w-full mt-6 px-4">
        <div className="flex justify-between text-[10px] text-gray-500 mb-1 uppercase font-bold">
          <span>Regen</span>
          <span className={`${consumption > 0 ? 'text-orange-400' : 'text-green-400'}`}>
            {consumption > 0 ? 'Power' : 'Charging'}
          </span>
          <span>Max</span>
        </div>
        <div className="h-2 w-full bg-gray-900 rounded-full overflow-hidden flex">
          <div 
            className="h-full bg-gradient-to-r from-green-500 via-cyan-400 to-orange-500 transition-all duration-300"
            style={{ width: `${consPct}%` }}
          />
        </div>
        <div className="flex justify-center mt-2">
            <span className="text-xs font-orbitron">{consumption.toFixed(1)} kW</span>
        </div>
      </div>
    </div>
  );
};

export default Speedometer;

