export default MapOverlay;

import React, { useState, useEffect, useCallback } from 'react';
import Speedometer from './components/Speedometer';
import MapOverlay from './components/MapOverlay';
import { RouteOption, EVState } from './types';
import { optimizeRoute, getEfficiencyTip } from './services/geminiService';

const App: React.FC = () => {
  const [routes, setRoutes] = useState<RouteOption[]>([]);
  const [selectedRouteId, setSelectedRouteId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [efficiencyTip, setEfficiencyTip] = useState<string>('Optimizing systems...');
  const [evState, setEvState] = useState<EVState>({
    currentSpeed: 65,
    recommendedSpeed: 82,
    batteryPercent: 48,
    rangeKm: 215,
    efficiencyWhKm: 142,
    instantConsumptionKw: 12.5
  });

  // Fetch routes on mount
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      const optimizedRoutes = await optimizeRoute("Silicon Valley Hub", evState.batteryPercent);
      setRoutes(optimizedRoutes);
      const optimal = optimizedRoutes.find(r => r.isOptimal) || optimizedRoutes[0];
      setSelectedRouteId(optimal.id);
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Real-time speed & tip updates
  useEffect(() => {
    const timer = setInterval(() => {
      setEvState(prev => ({
        ...prev,
        // Simulate slight fluctuations
        currentSpeed: Math.max(0, prev.currentSpeed + (Math.random() - 0.5) * 5),
        instantConsumptionKw: 10 + (Math.random() * 15)
      }));
    }, 1000);

    const tipTimer = setInterval(async () => {
      const tip = await getEfficiencyTip(evState.currentSpeed, evState.batteryPercent);
      setEfficiencyTip(tip);
    }, 8000);

    return () => {
      clearInterval(timer);
      clearInterval(tipTimer);
    };
  }, [evState.currentSpeed, evState.batteryPercent]);

  const selectedRoute = routes.find(r => r.id === selectedRouteId);
  const batteryAtDestination = selectedRoute ? evState.batteryPercent - selectedRoute.estimatedBatteryConsumption : 0;

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-black">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
          <div className="text-cyan-400 font-orbitron tracking-widest text-lg">SYSTEM INITIALIZING...</div>
          <div className="text-gray-500 text-sm italic">Analyzing topography & traffic patterns</div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-[#050505] p-4 gap-4">
      {/* Top Header Bar */}
      <header className="flex justify-between items-center px-6 py-3 glass-panel rounded-2xl h-16">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-xs text-gray-500 uppercase font-bold tracking-widest">Time</span>
            <span className="text-lg font-orbitron">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
          </div>
          <div className="h-8 w-[1px] bg-white/10"></div>
          <div className="flex flex-col">
            <span className="text-xs text-gray-500 uppercase font-bold tracking-widest">Efficiency</span>
            <span className="text-lg font-orbitron text-cyan-400">{evState.efficiencyWhKm} <span className="text-[10px] text-gray-500">Wh/km</span></span>
          </div>
        </div>

        <div className="flex items-center gap-8">
           <div className="flex items-center gap-3">
              <div className="flex flex-col items-end">
                <span className="text-xs text-gray-500 uppercase font-bold tracking-widest">Estimated Arrival</span>
                <span className="text-lg font-orbitron text-green-400">{batteryAtDestination.toFixed(1)}%</span>
              </div>
              <div className="w-12 h-6 border border-white/20 rounded flex items-center p-0.5 relative">
                 <div 
                   className={`h-full rounded-sm transition-all duration-1000 ${batteryAtDestination < 15 ? 'bg-red-500' : 'bg-green-500'}`} 
                   style={{ width: `${batteryAtDestination}%` }}
                 />
                 <div className="absolute -right-1.5 w-1 h-3 bg-white/30 rounded-r"></div>
              </div>
           </div>
        </div>
      </header>

      {/* Main Dashboard Layout */}
      <main className="flex-1 grid grid-cols-12 gap-4 min-h-0">
        {/* Left Side: Performance Gauges */}
        <div className="col-span-12 lg:col-span-4 flex flex-col gap-4">
          <div className="flex-1">
            <Speedometer 
               currentSpeed={evState.currentSpeed} 
               recommendedSpeed={evState.recommendedSpeed}
               consumption={evState.instantConsumptionKw}
            />
          </div>

          {/* Efficiency AI Tip Box */}
          <div className="glass-panel p-6 rounded-3xl border-l-4 border-l-cyan-500 shadow-xl">
             <div className="flex items-start gap-4">
                <div className="p-2 bg-cyan-500/20 rounded-xl">
                   <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                   </svg>
                </div>
                <div>
                  <h3 className="text-xs text-gray-400 uppercase font-bold tracking-widest mb-1">Eco-Intelligence Assistant</h3>
                  <p className="text-sm font-medium text-gray-200 leading-relaxed italic">
                    "{efficiencyTip}"
                  </p>
                </div>
             </div>
          </div>
        </div>

        {/* Right Side: Map and Navigation */}
        <div className="col-span-12 lg:col-span-8 flex flex-col gap-4">
          <div className="flex-1 min-h-[400px]">
            <MapOverlay 
              routes={routes} 
              selectedId={selectedRouteId} 
              onSelect={setSelectedRouteId} 
            />
          </div>

          {/* Detailed Route Stats */}
          <div className="glass-panel p-6 rounded-3xl flex items-center justify-between gap-6">
            <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Total Climb</span>
                <span className="text-xl font-orbitron">+{selectedRoute?.elevationGainM}m</span>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Total Descent</span>
                <span className="text-xl font-orbitron text-green-400">-{selectedRoute?.elevationLossM}m</span>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Traffic Index</span>
                <span className={`text-xl font-orbitron ${selectedRoute?.trafficLevel === 'High' ? 'text-red-500' : 'text-cyan-400'}`}>
                  {selectedRoute?.trafficLevel}
                </span>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Energy Cost</span>
                <span className="text-xl font-orbitron text-orange-400">{selectedRoute?.estimatedBatteryConsumption}%</span>
              </div>
            </div>

            <div className="w-[1px] h-12 bg-white/10 hidden md:block"></div>

            <div className="hidden md:flex flex-col max-w-[300px]">
               <span className="text-[10px] text-gray-500 uppercase font-bold">Smart Analysis</span>
               <p className="text-xs text-gray-400 leading-tight">
                {selectedRoute?.reasoning}
               </p>
            </div>
          </div>
        </div>
      </main>

      {/* Footer / Battery Warnings */}
      <footer className="h-12 flex items-center justify-center">
         {batteryAtDestination < 10 ? (
           <div className="bg-red-500/20 text-red-500 border border-red-500/50 px-6 py-1 rounded-full text-xs font-bold animate-pulse flex items-center gap-2">
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"/></svg>
              CRITICAL RANGE WARNING: DESTINATION ARRIVAL BELOW 10%
           </div>
         ) : (
           <div className="text-[10px] text-gray-600 uppercase tracking-widest font-bold">
             AI Active • Real-time traffic analysis enabled • Regenerative mapping optimized
           </div>
         )}
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Speedometer from './components/Speedometer';
import MapOverlay from './components/MapOverlay';
import { RouteOption, EVState } from './types';
import { optimizeRoute, getEfficiencyTip } from './services/geminiService';

const App: React.FC = () => {
  const [routes, setRoutes] = useState<RouteOption[]>([]);
  const [selectedRouteId, setSelectedRouteId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [destinationInput, setDestinationInput] = useState('Silicon Valley Hub');
  const [activeDestination, setActiveDestination] = useState('Silicon Valley Hub');
  const [efficiencyTip, setEfficiencyTip] = useState<string>('Optimizing systems...');
  const [evState, setEvState] = useState<EVState>({
    currentSpeed: 65,
    recommendedSpeed: 82,
    batteryPercent: 48,
    rangeKm: 215,
    efficiencyWhKm: 142,
    instantConsumptionKw: 12.5
  });

  const fetchRoutes = async (target: string) => {
    setIsUpdating(true);
    try {
      const optimizedRoutes = await optimizeRoute(target, evState.batteryPercent);
      setRoutes(optimizedRoutes);
      const optimal = optimizedRoutes.find(r => r.isOptimal) || optimizedRoutes[0];
      setSelectedRouteId(optimal.id);
      setActiveDestination(target);
    } catch (error) {
      console.error("Failed to fetch routes", error);
    } finally {
      setIsUpdating(false);
      setLoading(false);
    }
  };

  // Initial fetch
  useEffect(() => {
    fetchRoutes(activeDestination);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Real-time speed & tip updates
  useEffect(() => {
    const timer = setInterval(() => {
      setEvState(prev => ({
        ...prev,
        currentSpeed: Math.max(0, prev.currentSpeed + (Math.random() - 0.5) * 5),
        instantConsumptionKw: 10 + (Math.random() * 15)
      }));
    }, 1000);

    const tipTimer = setInterval(async () => {
      const tip = await getEfficiencyTip(evState.currentSpeed, evState.batteryPercent);
      setEfficiencyTip(tip);
    }, 8000);

    return () => {
      clearInterval(timer);
      clearInterval(tipTimer);
    };
  }, [evState.currentSpeed, evState.batteryPercent]);

  const handleDestinationSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (destinationInput.trim()) {
      fetchRoutes(destinationInput.trim());
    }
  };

  const selectedRoute = routes.find(r => r.id === selectedRouteId);
  const batteryAtDestination = selectedRoute ? evState.batteryPercent - selectedRoute.estimatedBatteryConsumption : 0;

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-black">
        <div className="flex flex-col items-center gap-6">
