import { optimizeRoute, getEfficiencyTip } from './services/geminiService';

const App: React.FC = () => {
  const [routes, setRoutes] = useState<RouteOption[]>([]);
  const [selectedRouteId, setSelectedRouteId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [destinationInput, setDestinationInput] = useState('Silicon Valley Hub');
  const [activeDestination, setActiveDestination] = useState('Silicon Valley Hub');
  const [efficiencyTip, setEfficiencyTip] = useState<string>('Optimizing systems...');
  const [userLoc, setUserLoc] = useState<{ latitude: number, longitude: number } | undefined>();

  const [evState, setEvState] = useState<EVState>({
    currentSpeed: 65,
    recommendedSpeed: 82,
    batteryPercent: 48,
    rangeKm: 215,
    efficiencyWhKm: 142,
    instantConsumptionKw: 12.5
  });

  const fetchRoutes = async (target: string, location?: { latitude: number, longitude: number }) => {
    setIsUpdating(true);
    try {
      const optimizedRoutes = await optimizeRoute(target, evState.batteryPercent, location);
      setRoutes(optimizedRoutes);
      const optimal = optimizedRoutes.find(r => r.isOptimal) || optimizedRoutes[0];
      setSelectedRouteId(optimal.id);
      setActiveDestination(target);
    } catch (error) {
      console.error("Failed to fetch routes", error);
    } finally {
      setIsUpdating(false);
      setLoading(false);
    }
  };

  // Get Geolocation and Initial Routes
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setUserLoc(loc);
          fetchRoutes(activeDestination, loc);
        },
        () => {
          fetchRoutes(activeDestination);
        }
      );
    } else {
      fetchRoutes(activeDestination);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Real-time speed & tip updates
  useEffect(() => {
    const timer = setInterval(() => {
      setEvState(prev => ({
        ...prev,
        currentSpeed: Math.max(0, prev.currentSpeed + (Math.random() - 0.5) * 5),
        instantConsumptionKw: 10 + (Math.random() * 15)
      }));
    }, 1000);

    const tipTimer = setInterval(async () => {
      const tip = await getEfficiencyTip(evState.currentSpeed, evState.batteryPercent);
      setEfficiencyTip(tip);
    }, 12000);

    return () => {
      clearInterval(timer);
      clearInterval(tipTimer);
    };
  }, [evState.currentSpeed, evState.batteryPercent]);

  const handleDestinationSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (destinationInput.trim()) {
      fetchRoutes(destinationInput.trim(), userLoc);
    }
  };

  const selectedRoute = routes.find(r => r.id === selectedRouteId);
  const batteryAtDestination = selectedRoute ? evState.batteryPercent - selectedRoute.estimatedBatteryConsumption : 0;

  // Calculate ETA relative to current time
  const arrivalTime = selectedRoute ? new Date(Date.now() + selectedRoute.durationMin * 60000) : null;

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-black">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
          <div className="text-cyan-400 font-orbitron tracking-widest text-lg">GPS CONNECTING...</div>
          <div className="text-gray-500 text-sm italic">Synchronizing with Google Maps API</div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-[#050505] p-4 gap-4 overflow-hidden">
      {/* Top Header Bar */}
      <header className="flex justify-between items-center px-6 py-3 glass-panel rounded-2xl h-20 shadow-xl">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Time to reach</span>
            <span className="text-lg font-orbitron text-cyan-400">
              {selectedRoute ? `${selectedRoute.durationMin} MINS` : '--'}
            </span>
          </div>
          <div className="h-10 w-[1px] bg-white/10"></div>

          {/* Destination Form */}
          <form onSubmit={handleDestinationSubmit} className="flex items-center gap-2">
            <div className="flex flex-col">
              <label className="text-[10px] text-gray-500 uppercase font-bold tracking-widest mb-0.5">Route Destination</label>
              <input 
                type="text" 
                value={destinationInput}
                onChange={(e) => setDestinationInput(e.target.value)}
                className="bg-black/40 border border-white/10 rounded-lg px-3 py-1 text-sm font-semibold focus:outline-none focus:border-cyan-500/50 transition-all w-48 md:w-80"
                placeholder="Enter destination..."
              />
            </div>
            <button 
              type="submit"
              disabled={isUpdating}
              className="mt-4 p-2.5 bg-cyan-500/20 hover:bg-cyan-500/30 rounded-lg border border-cyan-500/30 transition-all"
            >
              {isUpdating ? (
                <div className="w-4 h-4 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <svg className="w-4 h-4 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                </svg>
              )}
            </button>
          </form>
        </div>

        <div className="flex items-center gap-10">
           <div className="flex flex-col items-end">
              <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">ETA</span>
              <span className="text-lg font-orbitron text-white">
                {arrivalTime?.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) || '--:--'}
              </span>
           </div>

           <div className="flex items-center gap-3">
              <div className="flex flex-col items-end">
                <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Est. Arrival Battery</span>
