const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function optimizeRoute(
  destination: string, 
  currentBattery: number, 
  userLocation?: { latitude: number; longitude: number }
): Promise<RouteOption[]> {
  try {
    const prompt = `Analyze the best EV routes to "${destination}" from ${userLocation ? `current location [lat: ${userLocation.latitude}, lng: ${userLocation.longitude}]` : 'my current location'}. 
    Current EV battery: ${currentBattery}%. 
    Focus on elevation profiles (uphill/downhill), traffic, and regenerative braking.

    IMPORTANT: Return exactly 3 distinct route options.
    One route MUST be the most energy optimal (utilizing downhills for regen).
    One route MUST be the fastest (even if less efficient).
    One route MUST be a balanced choice.

    Output the data as a raw JSON array of objects with these keys: 
    "id" (string), "name" (string), "distanceKm" (number), "durationMin" (number), "elevationGainM" (number), "elevationLossM" (number), "trafficLevel" ("Low"|"Moderate"|"High"), "estimatedBatteryConsumption" (number percentage), "isOptimal" (boolean), "reasoning" (string).

    Provide ONLY the raw JSON array. No conversational text, no markdown code blocks.`;

    // Note: Gemini 2.5 series is required for Google Maps grounding.
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite-latest",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: userLocation ? {
              latitude: userLocation.latitude,
              longitude: userLocation.longitude
            } : undefined
          }
        },
        // responseMimeType and responseSchema are NOT supported when using googleMaps tool.
      }
    });

    let text = response.text || "";

    // Attempt to extract JSON if the model wrapped it in markdown or added fluff
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) {
      text = jsonMatch[0];
