    const prompt = `Act as an EV navigation expert. Analyze the best 3 routes to "${destination}" from ${userLocation ? `current location [lat: ${userLocation.latitude}, lng: ${userLocation.longitude}]` : 'my current location'}. 
    Current EV battery: ${currentBattery}%. 
    Focus on elevation profiles (uphill/downhill), real-time traffic, and regenerative braking.

    You MUST return a JSON array of 3 objects. 
    Required Route Types:
    1. "Eco-Optimal": Maximizes downhill regeneration and minimizes steep climbs.
    2. "Fastest": Prioritizes arrival time despite higher energy consumption.
    3. "Balanced": A middle ground between speed and battery preservation.

    Each object must have exactly these keys:
    "id": string (e.g., "1", "2", "3")
    "name": string (Route name)
    "distanceKm": number (Total km)
    "durationMin": number (Total minutes)
    "elevationGainM": number (Total uphill meters)
    "elevationLossM": number (Total downhill/regen meters)
    "trafficLevel": "Low" | "Moderate" | "High"
    "estimatedBatteryConsumption": number (Estimated percentage of battery used, e.g., 8.5)
    "isOptimal": boolean (True only for the Eco-Optimal route)
    "reasoning": string (Short explanation of energy profile)

    Output format: [ { ... }, { ... }, { ... } ]
    IMPORTANT: Provide ONLY the raw JSON array. Do not include markdown code blocks (\`\`\`json), no introductory text, no conversational filler.`;

    // Maps grounding is specifically supported in the gemini-2.5-flash model.
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: userLocation ? {
              latitude: userLocation.latitude,
              longitude: userLocation.longitude
            } : undefined
          }
        },
        // responseMimeType is incompatible with googleMaps tool, 
        // so we must parse the raw text response.
      }
    });

    const rawText = response.text || "";
    if (!rawText || rawText.trim() === "") {
      throw new Error("Empty response from model");
    }

    // Attempt to extract the JSON array using a robust regex that finds the first [ and last ]
    let jsonString = "";
    const startIdx = rawText.indexOf('[');
    const endIdx = rawText.lastIndexOf(']');

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
      jsonString = rawText.substring(startIdx, endIdx + 1);
