import { optimizeRoute, getEfficiencyTip } from './services/geminiService';

const App: React.FC = () => {
  const [routes, setRoutes] = useState<RouteOption[]>([]);
  const [selectedRouteId, setSelectedRouteId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [destinationInput, setDestinationInput] = useState('Silicon Valley Hub');
  const [activeDestination, setActiveDestination] = useState('Silicon Valley Hub');
  const [efficiencyTip, setEfficiencyTip] = useState<string>('Optimizing systems...');
  const [userLoc, setUserLoc] = useState<{ latitude: number, longitude: number } | undefined>();

  const [evState, setEvState] = useState<EVState>({
    currentSpeed: 65,
    recommendedSpeed: 82,
    batteryPercent: 48,
    rangeKm: 215,
    efficiencyWhKm: 142,
    instantConsumptionKw: 12.5
  });

  const fetchRoutes = async (target: string, location?: { latitude: number, longitude: number }) => {
    setIsUpdating(true);
    try {
      const optimizedRoutes = await optimizeRoute(target, evState.batteryPercent, location);
      setRoutes(optimizedRoutes);
      const optimal = optimizedRoutes.find(r => r.isOptimal) || optimizedRoutes[0];
      setSelectedRouteId(optimal.id);
      setActiveDestination(target);
    } catch (error) {
      console.error("Failed to fetch routes", error);
    } finally {
      setIsUpdating(false);
      setLoading(false);
    }
  };

  // Get Geolocation and Initial Routes
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setUserLoc(loc);
          fetchRoutes(activeDestination, loc);
        },
        () => {
          fetchRoutes(activeDestination);
        }
      );
    } else {
      fetchRoutes(activeDestination);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Real-time speed & tip updates
  useEffect(() => {
    const timer = setInterval(() => {
      setEvState(prev => ({
        ...prev,
        currentSpeed: Math.max(0, prev.currentSpeed + (Math.random() - 0.5) * 5),
        instantConsumptionKw: 10 + (Math.random() * 15)
      }));
    }, 1000);

    const tipTimer = setInterval(async () => {
      const tip = await getEfficiencyTip(evState.currentSpeed, evState.batteryPercent);
      setEfficiencyTip(tip);
    }, 12000);

    return () => {
      clearInterval(timer);
      clearInterval(tipTimer);
    };
  }, [evState.currentSpeed, evState.batteryPercent]);

  const handleDestinationSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (destinationInput.trim()) {
      fetchRoutes(destinationInput.trim(), userLoc);
    }
  };

  const selectedRoute = routes.find(r => r.id === selectedRouteId);
  const batteryAtDestination = selectedRoute ? evState.batteryPercent - selectedRoute.estimatedBatteryConsumption : 0;

  // Calculate ETA relative to current time
  const arrivalTime = selectedRoute ? new Date(Date.now() + selectedRoute.durationMin * 60000) : null;

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-black">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
          <div className="text-cyan-400 font-orbitron tracking-widest text-lg">GPS CONNECTING...</div>
          <div className="text-gray-500 text-sm italic">Synchronizing with Google Maps API</div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-[#050505] p-4 gap-4 overflow-hidden">
      {/* Top Header Bar */}
      <header className="flex justify-between items-center px-6 py-3 glass-panel rounded-2xl h-20 shadow-xl border-b border-white/5">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Time to reach</span>
            <span className="text-lg font-orbitron text-cyan-400">
              {selectedRoute ? `${selectedRoute.durationMin} MINS` : '--'}
            </span>
          </div>
          <div className="h-10 w-[1px] bg-white/10"></div>

          {/* Destination Form */}
          <form onSubmit={handleDestinationSubmit} className="flex items-center gap-2">
            <div className="flex flex-col">
              <label className="text-[10px] text-gray-500 uppercase font-bold tracking-widest mb-0.5">Route Destination</label>
              <input 
                type="text" 
                value={destinationInput}
                onChange={(e) => setDestinationInput(e.target.value)}
                className="bg-black/40 border border-white/10 rounded-lg px-3 py-1 text-sm font-semibold focus:outline-none focus:border-cyan-500/50 transition-all w-48 md:w-80"
                placeholder="Enter destination..."
              />
            </div>
            <button 
              type="submit"
              disabled={isUpdating}
              className="mt-4 p-2.5 bg-cyan-500/20 hover:bg-cyan-500/30 rounded-lg border border-cyan-500/30 transition-all"
            >
              {isUpdating ? (
                <div className="w-4 h-4 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <svg className="w-4 h-4 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                </svg>
              )}
            </button>
          </form>
        </div>

        <div className="flex items-center gap-10">
           <div className="flex flex-col items-end">
              <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">ETA</span>
              <span className="text-lg font-orbitron text-white">
                {arrivalTime?.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) || '--:--'}
              </span>
           </div>

           <div className="flex items-center gap-3">
              <div className="flex flex-col items-end">
                <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Est. Arrival Battery</span>
                <span className={`text-lg font-orbitron ${batteryAtDestination < 15 ? 'text-red-400' : 'text-green-400'}`}>
                  {batteryAtDestination.toFixed(1)}%
                </span>
              </div>
              <div className="w-14 h-7 border border-white/20 rounded-md flex items-center p-0.5 relative">
                 <div 
                   className={`h-full rounded-sm transition-all duration-1000 ${batteryAtDestination < 15 ? 'bg-red-500 shadow-[0_0_15px_#ef4444]' : 'bg-green-500 shadow-[0_0_10px_#22c55e44]'}`} 
                   style={{ width: `${Math.max(2, Math.min(100, batteryAtDestination))}%` }}
                 />
                 <div className="absolute -right-1.5 w-1.5 h-3.5 bg-white/30 rounded-r"></div>
              </div>
           </div>
        </div>
      </header>

      {/* Main Dashboard Layout - SWAPPED FOR ERGONOMICS */}
      <main className="flex-1 grid grid-cols-12 gap-4 min-h-0">
        {/* Left/Middle Area: Map and Navigation (Primary Focus) */}
        <div className="col-span-12 lg:col-span-8 flex flex-col gap-4">
          <div className="flex-1 min-h-[300px]">
            <MapOverlay 
              routes={routes} 
              selectedId={selectedRouteId} 
              onSelect={setSelectedRouteId} 
              destinationName={activeDestination}
            />
          </div>

          {/* Detailed Route Stats */}
          <div className="glass-panel p-6 rounded-3xl flex items-center justify-between gap-6 border border-white/5 shadow-xl">
            <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Total Distance</span>
                <span className="text-xl font-orbitron text-cyan-400">{selectedRoute?.distanceKm} km</span>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Total Climb/Descent</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-orbitron text-red-400">+{selectedRoute?.elevationGainM}m</span>
                  <span className="text-sm font-orbitron text-green-400">-{selectedRoute?.elevationLossM}m</span>
                </div>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Traffic Index</span>
                <span className={`text-xl font-orbitron ${selectedRoute?.trafficLevel === 'High' ? 'text-red-500' : 'text-cyan-400'}`}>
                  {selectedRoute?.trafficLevel}
                </span>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Trip Energy</span>
                <span className="text-xl font-orbitron text-orange-400">{selectedRoute?.estimatedBatteryConsumption}%</span>
              </div>
            </div>

            <div className="w-[1px] h-12 bg-white/10 hidden md:block"></div>

            <div className="hidden md:flex flex-col max-w-[300px]">
               <span className="text-[10px] text-gray-500 uppercase font-bold">Smart Analysis</span>
               <p className="text-xs text-gray-400 leading-tight">
                {selectedRoute?.reasoning}
               </p>
            </div>
          </div>
        </div>

        {/* Right Side: Performance Gauges (Driver Side Focus) */}
        <div className="col-span-12 lg:col-span-4 flex flex-col gap-4">
          <div className="flex-1">
            <Speedometer 
               currentSpeed={evState.currentSpeed} 
               recommendedSpeed={evState.recommendedSpeed}
               consumption={evState.instantConsumptionKw}
            />
          </div>

          {/* Efficiency AI Tip Box */}
          <div className="glass-panel p-6 rounded-3xl border-l-4 border-l-cyan-500 shadow-xl">
             <div className="flex items-start gap-4">
                <div className="p-2 bg-cyan-500/20 rounded-xl">
                   <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                   </svg>
                </div>
                <div className="flex-1">
                  <h3 className="text-[10px] text-gray-400 uppercase font-bold tracking-widest mb-1">Eco-Intelligence Assistant</h3>
                  <p className="text-sm font-medium text-gray-200 leading-relaxed italic">
                    "{efficiencyTip}"
                  </p>
                </div>
             </div>
          </div>
        </div>
      </main>

      {/* Footer / Battery Warnings */}
      <footer className="h-10 flex items-center justify-center">
         {batteryAtDestination < 10 ? (
           <div className="bg-red-500/20 text-red-500 border border-red-500/50 px-6 py-1 rounded-full text-[10px] font-bold animate-pulse flex items-center gap-2">
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"/></svg>
              CRITICAL RANGE WARNING: DESTINATION IS BEYOND CURRENT ECO-RANGE LIMITS
           </div>
         ) : (
           <div className="text-[10px] text-gray-600 uppercase tracking-widest font-bold">
             Google Maps Grounding Active • Real-time traffic analysis enabled • Regenerative mapping optimized
           </div>
         )}
      </footer>
    </div>
  );
};

export default App;

