            <button
              key={route.id}
              onClick={() => onSelect(route.id)}
              className={`px-5 py-3 rounded-2xl transition-all flex items-center gap-4 ${
                selectedId === route.id 
                ? 'bg-cyan-500/20 border border-cyan-500/50 shadow-[0_0_30px_rgba(6,182,212,0.25)]' 
                : 'bg-black/60 border border-white/10 hover:bg-white/5 backdrop-blur-md'
              }`}
            >
              <div className={`w-2.5 h-2.5 rounded-full ${selectedId === route.id ? 'bg-cyan-400 animate-pulse' : 'bg-gray-600'}`}></div>
              <div className="text-left flex-1">
                <div className="text-xs font-bold uppercase tracking-widest leading-none mb-1">{route.name}</div>
                <div className="text-[10px] text-gray-400 font-semibold">
                  {route.distanceKm}km • {route.durationMin}m • {route.trafficLevel} Traffic
                </div>
              </div>
              {route.isOptimal && (
                <span className="ml-4 bg-green-500/20 text-green-400 text-[9px] px-2 py-1 rounded-lg border border-green-500/30 font-black tracking-tighter">
                  ECO OPTIMAL
                </span>
              )}
            </button>
          ))}
