        {/* Map UI Elements - Top Right Overlay */}
        <div className="absolute top-6 right-6 flex flex-col gap-3 z-10">
            <div className="p-4 glass-panel rounded-2xl flex items-center gap-4 border border-white/10 shadow-2xl">
               <div className="w-10 h-10 bg-green-500/20 rounded-xl flex items-center justify-center border border-green-500/20">
