                href={selectedRoute.mapUri} 
                target="_blank" 
                rel="noopener noreferrer"
                className="group p-3 bg-white/5 hover:bg-white/10 glass-panel rounded-2xl flex items-center gap-3 border border-white/10 transition-all text-cyan-400 shadow-xl"
              >
                <div className="p-1.5 bg-cyan-500/10 rounded-lg">
