): Promise<RouteOption[]> {
  try {
    // We use gemini-2.5-flash for Google Maps grounding support.
    // We explicitly ask for a JSON response in the prompt.
    const prompt = `You are a professional EV routing assistant. Use Google Maps to find 3 energy-efficient routes to "${destination}" from ${userLocation ? `current location [lat: ${userLocation.latitude}, lng: ${userLocation.longitude}]` : 'my current location'}.

    Current Battery: ${currentBattery}%

    REQUIRED OUTPUT: A raw JSON array of 3 route objects. No markdown, no conversational text.
    Each object must have:
    - id: string ("1", "2", "3")
    - name: string (e.g. "Eco-Optimal Route")
    - distanceKm: number
    - durationMin: number
    - elevationGainM: number
    - elevationLossM: number
    - trafficLevel: "Low" | "Moderate" | "High"
    - estimatedBatteryConsumption: number (percentage)
    - isOptimal: boolean (true for the most efficient route)
    - reasoning: string (focus on elevation and regen potential)

    Prioritize routes with more 'elevationLossM' as they allow for regenerative braking. Avoid high 'elevationGainM' if possible. Check real-time traffic to ensure 'durationMin' is accurate.`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }, { googleSearch: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: userLocation ? {
              latitude: userLocation.latitude,
              longitude: userLocation.longitude
            } : undefined
          }
        },
        // We cannot use responseMimeType: "application/json" with googleMaps tool.
      }
    });

    let text = response.text || "";

    // Sometimes response.text is empty but the content is in the parts
    if (!text && response.candidates?.[0]?.content?.parts) {
      text = response.candidates[0].content.parts
        .map(part => part.text || "")
        .join("")
        .trim();
    }

    if (!text) {
      // If still no text, check if grounding exists. If grounding exists but no text, 
      // the model might have found info but failed to summarize.
      if (response.candidates?.[0]?.groundingMetadata) {
        console.debug("Grounding metadata found but no text summary. Using fallback.");
