          }
        });
      }

      return routes;
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, "Raw Text:", text);
      throw new Error("Invalid JSON format in model response");
    }

  } catch (error) {
    console.error("Gemini Route Optimization Error:", error);

    // Robust Fallback Data
    return [
      {
        id: "1",
        name: "Eco-Regen Priority",
        distanceKm: 22.4,
        durationMin: 28,
        elevationGainM: 45,
        elevationLossM: 180,
