      },
      {
        id: "2",
        name: "Express Route",
        distanceKm: 25.1,
        durationMin: 22,
        elevationGainM: 60,
        elevationLossM: 60,
        trafficLevel: 'Moderate',
        estimatedBatteryConsumption: 11.5,
        isOptimal: false,
        reasoning: "Faster arrival time via highway, but higher sustained speeds increase energy consumption.",
        mapUri: `https://www.google.com/maps/search/${encodeURIComponent(destination)}`
      },
      {
        id: "3",
