import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { RouteOption } from '../types';

interface Props {
  routes: RouteOption[];
  selectedId: string;
  onSelect: (id: string) => void;
  destinationName: string;
}

const VIT_CHENNAI_COORDS: [number, number] = [12.8406, 80.1534];

const MapOverlay: React.FC<Props> = ({ routes, selectedId, onSelect, destinationName }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const routeLayersRef = useRef<L.LayerGroup | null>(null);
  const markersLayerRef = useRef<L.LayerGroup | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    // Initialize map
    mapRef.current = L.map(mapContainerRef.current, {
      center: VIT_CHENNAI_COORDS,
      zoom: 13,
      zoomControl: false,
      attributionControl: false
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(mapRef.current);

    routeLayersRef.current = L.layerGroup().addTo(mapRef.current);
    markersLayerRef.current = L.layerGroup().addTo(mapRef.current);

    return () => {
      mapRef.current?.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!mapRef.current || !routeLayersRef.current || !markersLayerRef.current) return;

    routeLayersRef.current.clearLayers();
    markersLayerRef.current.clearLayers();

    const selectedRoute = routes.find(r => r.id === selectedId);

    // In a real app, we'd have exact destination coordinates. 
    // For this demo, we'll simulate a point based on distance if we don't have real grounding.
    // Let's assume the destination is north-east of VIT for visualization.
    const distanceFactor = (selectedRoute?.distanceKm || 10) / 100;
    const destCoords: [number, number] = [
      VIT_CHENNAI_COORDS[0] + (distanceFactor * 0.5), 
      VIT_CHENNAI_COORDS[1] + (distanceFactor * 0.8)
    ];

    // Add Start Marker
    L.circleMarker(VIT_CHENNAI_COORDS, {
      radius: 8,
      fillColor: '#06b6d4',
      color: '#fff',
      weight: 2,
      opacity: 1,
      fillOpacity: 0.8
    }).addTo(markersLayerRef.current).bindPopup('Start: VIT Chennai');

    // Add Destination Marker
    L.marker(destCoords, {
      icon: L.divIcon({
        className: 'custom-div-icon',
        html: `<div style="background-color: #22c55e; width: 12px; height: 12px; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 10px #22c55e;"></div>`,
        iconSize: [12, 12],
        iconAnchor: [6, 6]
      })
    }).addTo(markersLayerRef.current).bindPopup(`Destination: ${destinationName}`);

    // Draw Routes
    routes.forEach(route => {
      const isSelected = route.id === selectedId;

      // Create a slightly curved path (simulated routing)
      const latlngs: [number, number][] = [VIT_CHENNAI_COORDS];

      // Add midpoints for curve
      const steps = 10;
      for(let i = 1; i < steps; i++) {
        const ratio = i / steps;
        const lat = VIT_CHENNAI_COORDS[0] + (destCoords[0] - VIT_CHENNAI_COORDS[0]) * ratio + (Math.sin(ratio * Math.PI) * 0.02 * (route.id === '1' ? 1 : -1));
        const lng = VIT_CHENNAI_COORDS[1] + (destCoords[1] - VIT_CHENNAI_COORDS[1]) * ratio + (Math.cos(ratio * Math.PI) * 0.02 * (route.id === '2' ? 1 : 0.5));
        latlngs.push([lat, lng]);
      }
      latlngs.push(destCoords);

      const polyline = L.polyline(latlngs, {
        color: isSelected ? '#06b6d4' : '#333',
        weight: isSelected ? 6 : 3,
        opacity: isSelected ? 0.9 : 0.4,
        lineCap: 'round'
      }).addTo(routeLayersRef.current!);

      if (isSelected) {
        // Add Charging Stops Markers
        route.chargingStops?.forEach((stop, idx) => {
          const stopRatio = Math.min(0.9, (stop.kmAt / route.distanceKm));
          const stopIdx = Math.floor(stopRatio * (latlngs.length - 1));
          const stopCoords = latlngs[stopIdx];

          L.marker(stopCoords, {
            icon: L.divIcon({
              className: 'charging-icon',
              html: `
                <div style="background-color: #f97316; width: 24px; height: 24px; border-radius: 6px; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 15px rgba(249,115,22,0.6); border: 2px solid white;">
                  <svg style="width: 14px; height: 14px; color: white;" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                </div>
              `,
              iconSize: [24, 24],
              iconAnchor: [12, 12]
            })
          }).addTo(markersLayerRef.current!).bindPopup(stop.label);
        });

        // Fit map to bounds
        mapRef.current?.fitBounds(polyline.getBounds(), { padding: [50, 50] });
      }
    });

  }, [routes, selectedId, destinationName]);

  return (
    <div className="relative w-full h-full glass-panel rounded-3xl overflow-hidden border border-white/5 shadow-2xl">
      <div ref={mapContainerRef} className="w-full h-full z-0" />

      {/* Route Selection Overlays */}
      <div className="absolute bottom-6 left-6 flex flex-col gap-2 z-[1000]">
        {routes.map(route => (
          <button
            key={route.id}
            onClick={() => onSelect(route.id)}
            className={`px-4 py-3 rounded-xl transition-all flex items-center gap-4 text-left ${
              selectedId === route.id ? 'bg-cyan-500/30 border border-cyan-500/50 backdrop-blur-md shadow-lg scale-105' : 'bg-black/80 border border-white/10 hover:bg-black/90'
            }`}
          >
            <div className="flex-1">
              <div className="text-[10px] font-black uppercase tracking-widest text-cyan-400 mb-0.5">{route.name}</div>
              <div className="text-xs font-bold text-white">
                {route.distanceKm}km • {route.durationMin}m
              </div>
            </div>
            {route.distanceKm > 100 && (
              <div className="bg-orange-500/20 text-orange-400 p-1 rounded-md border border-orange-500/30">
                <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
            )}
          </button>
        ))}
      </div>

      {/* Map Legend Overlay */}
      <div className="absolute top-6 right-6 p-3 bg-black/80 border border-white/10 rounded-xl backdrop-blur-md z-[1000] flex flex-col gap-2">
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-cyan-500 shadow-[0_0_5px_#06b6d4]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">Current Pos (VIT)</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-green-500 shadow-[0_0_5px_#22c55e]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">Target Location</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded bg-orange-500 shadow-[0_0_5px_#f97316]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">Charge Waypoint</span>
         </div>
      </div>
    </div>
  );
};

