import { GoogleGenAI, Type } from "@google/genai";
import { RouteOption } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export interface EnhancedRouteOption extends RouteOption {
  isSimulated?: boolean;
}

// Local lookup for common destinations to "improvise" distance when API fails
const LOCAL_DISTANCE_ESTIMATOR: Record<string, number> = {
  'chennai': 32,
  'marina': 35,
  'tambaram': 12,
  'guindy': 24,
  'pondy': 120,
  'pondicherry': 120,
  'bangalore': 330,
  'bengaluru': 330,
  'coimbatore': 480,
  'madurai': 430,
  'vellore': 120,
  'vit vellore': 125,
  'airport': 18,
  'chennai airport': 18,
  'thiruvanmiyur': 28,
  'adyar': 30,
};

function estimateDistance(destination: string): number {
  const normalized = destination.toLowerCase().trim();
  // Check if it's in our local map
  for (const [key, value] of Object.entries(LOCAL_DISTANCE_ESTIMATOR)) {
    if (normalized.includes(key)) return value;
  }

  // Generic estimation based on string length and random factor for variety
  // This "improvises" a plausible distance when we have no other data
  const base = 15 + (destination.length * 2);
  const jitter = Math.floor(Math.random() * 10);
  return base + jitter;
}

export async function optimizeRoute(
  destination: string, 
  currentBattery: number, 
  userLocation?: { latitude: number; longitude: number }
): Promise<EnhancedRouteOption[]> {
  try {
    const prompt = `You are an expert EV routing engine. 
    TASK: Find 3 potential routes to "${destination}" from the start point 'VIT Chennai' (coordinates: 12.8406, 80.1534).

    1. Use Google Maps to get real-time routing and traffic.
    2. IMPORTANT: Use your internal knowledge of terrain to ESTIMATE 'elevationGainM', 'elevationLossM', and 'estimatedBatteryConsumption'.
    3. Ensure one route is "Eco-Optimal" (best for range), one is "Fastest", and one is "Balanced".

    OUTPUT FORMAT: Return ONLY a raw JSON array. Do not apologize. 

    Schema:
    [
      {
        "id": "1",
        "name": "Route Name",
        "distanceKm": number,
        "durationMin": number,
        "elevationGainM": number,
        "elevationLossM": number,
        "trafficLevel": "Low" | "Moderate" | "High",
        "estimatedBatteryConsumption": number,
        "isOptimal": boolean,
        "reasoning": "Explain why this route is good for an EV"
      }
    ]

    Current Vehicle Battery: ${currentBattery}%`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: {
              latitude: 12.8406,
              longitude: 80.1534
            }
          }
        },
      }
    });

    let text = "";
    if (response.candidates?.[0]?.content?.parts) {
      text = response.candidates[0].content.parts
        .map(part => part.text || "")
        .join("")
        .trim();
    }

    if (!text || text.toLowerCase().includes("i am sorry") || text.toLowerCase().includes("cannot fulfill")) {
      throw new Error("Refusal or empty response");
    }

    const jsonMatch = text.match(/\[\s*\{[\s\S]*\}\s*\]/);
    const jsonString = jsonMatch ? jsonMatch[0] : text.trim();

    const routes: EnhancedRouteOption[] = JSON.parse(jsonString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks && Array.isArray(routes)) {
      routes.forEach((route) => {
        const mapsChunk = groundingChunks.find(chunk => chunk.maps?.uri);
        route.mapUri = mapsChunk?.maps?.uri || `https://www.google.com/maps/search/${encodeURIComponent(destination)}`;
        route.isSimulated = false;
      });
    }

    return routes;

  } catch (error: any) {
    const isQuotaError = error?.message?.includes("quota") || error?.message?.includes("429");
    console.warn(isQuotaError ? "API Quota Exceeded. Using Improvised Distance Estimation." : "Gemini Error:", error);

    // Improvised distance calculation from VIT Chennai
    const estimatedDist = estimateDistance(destination);
    const estimatedTime = Math.round(estimatedDist * 1.8); // Simple 1.8 min/km avg
    const baseConsumption = Math.min(currentBattery - 5, (estimatedDist / 100) * 20); 

    return [
      {
        id: "1",
        name: "Improvised Eco-Optimal",
        distanceKm: estimatedDist,
        durationMin: estimatedTime,
        elevationGainM: 20,
        elevationLossM: 10,
        trafficLevel: 'Low',
        estimatedBatteryConsumption: Number((baseConsumption * 0.9).toFixed(1)),
        isOptimal: true,
        isSimulated: true,
        reasoning: `SIMULATED: Estimated ${estimatedDist}km distance from VIT Chennai based on destination heuristics.`,
        mapUri: `https://www.google.com/maps/search/${encodeURIComponent(destination)}`
      },
      {
        id: "2",
        name: "Improvised Fast-Path",
        distanceKm: Number((estimatedDist * 1.1).toFixed(1)),
        durationMin: Math.round(estimatedTime * 0.8),
        elevationGainM: 40,
        elevationLossM: 30,
        trafficLevel: 'Moderate',
        estimatedBatteryConsumption: Number((baseConsumption * 1.3).toFixed(1)),
        isOptimal: false,
        isSimulated: true,
        reasoning: "SIMULATED: Highway estimation with moderate traffic modeling.",
        mapUri: `https://www.google.com/maps/search/${encodeURIComponent(destination)}`
      },
      {
        id: "3",
        name: "Improvised Balanced",
        distanceKm: Number((estimatedDist * 1.05).toFixed(1)),
        durationMin: Math.round(estimatedTime * 0.95),
        elevationGainM: 30,
        elevationLossM: 20,
        trafficLevel: 'Moderate',
        estimatedBatteryConsumption: Number(baseConsumption.toFixed(1)),
        isOptimal: false,
        isSimulated: true,
        reasoning: "SIMULATED: Balanced route considering distance and traffic standard deviation.",
        mapUri: `https://www.google.com/maps/search/${encodeURIComponent(destination)}`
      }
    ];
  }
}

export async function getEfficiencyTip(speed: number, battery: number): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Status: Stationary vehicle, ${battery}% battery. Short EV tip (max 8 words).`,
    });
    return response.text.trim().replace(/^"|"$/g, '');
  } catch (error) {
    return "Check tire pressure for optimal range.";
  }
}

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { RouteOption } from '../types';

interface Props {
  routes: RouteOption[];
  selectedId: string;
  onSelect: (id: string) => void;
  destinationName: string;
}

const VIT_CHENNAI_COORDS: [number, number] = [12.8406, 80.1534];

const MapOverlay: React.FC<Props> = ({ routes, selectedId, onSelect, destinationName }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const routeLayersRef = useRef<L.LayerGroup | null>(null);
  const markersLayerRef = useRef<L.LayerGroup | null>(null);
  const [roadGeometry, setRoadGeometry] = useState<Record<string, [number, number][]>>({});

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    // Initialize map
    mapRef.current = L.map(mapContainerRef.current, {
      center: VIT_CHENNAI_COORDS,
      zoom: 13,
      zoomControl: false,
      attributionControl: false
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(mapRef.current);

    routeLayersRef.current = L.layerGroup().addTo(mapRef.current);
    markersLayerRef.current = L.layerGroup().addTo(mapRef.current);

    return () => {
      mapRef.current?.remove();
      mapRef.current = null;
    };
  }, []);

  // Fetch real road geometry from OSRM
  useEffect(() => {
    const fetchRoadPaths = async () => {
      if (!destinationName) return;

      try {
        // 1. Geocode the destination
        const geoRes = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(destinationName)}&limit=1`);
        const geoData = await geoRes.json();

        if (!geoData || geoData.length === 0) return;

        const destLat = parseFloat(geoData[0].lat);
        const destLng = parseFloat(geoData[0].lon);

        // 2. Fetch Route from OSRM
        // We simulate 3 routes by slightly shifting mid-points if possible, 
        // but OSRM gives us the primary road path.
        const osrmUrl = `https://router.project-osrm.org/route/v1/driving/${VIT_CHENNAI_COORDS[1]},${VIT_CHENNAI_COORDS[0]};${destLng},${destLat}?overview=full&geometries=geojson`;
        const routeRes = await fetch(osrmUrl);
        const routeData = await routeRes.json();

        if (routeData.code === 'Ok' && routeData.routes.length > 0) {
          const coords = routeData.routes[0].geometry.coordinates.map((c: any) => [c[1], c[0]] as [number, number]);

          // Create variations for the 3 route options (simulated deviations for UI)
          const newGeoms: Record<string, [number, number][]> = {
            '1': coords, // Primary
            '2': coords.map(c => [c[0] + 0.001, c[1] + 0.001] as [number, number]), // Offset
            '3': coords.map(c => [c[0] - 0.001, c[1] - 0.001] as [number, number])  // Offset
          };
          setRoadGeometry(newGeoms);
        }
      } catch (err) {
        console.error("Routing error:", err);
      }
    };

    fetchRoadPaths();
  }, [destinationName]);

  useEffect(() => {
    if (!mapRef.current || !routeLayersRef.current || !markersLayerRef.current) return;

    routeLayersRef.current.clearLayers();
    markersLayerRef.current.clearLayers();

    const selectedRoute = routes.find(r => r.id === selectedId);
    const activeCoords = roadGeometry[selectedId] || roadGeometry['1'];

    // If no road geometry yet, don't draw
    if (!activeCoords || activeCoords.length === 0) return;

    const destCoords = activeCoords[activeCoords.length - 1];

    // Add Start Marker
    L.circleMarker(VIT_CHENNAI_COORDS, {
      radius: 8,
      fillColor: '#06b6d4',
      color: '#fff',
      weight: 2,
      opacity: 1,
      fillOpacity: 0.8
    }).addTo(markersLayerRef.current).bindPopup('Start: VIT Chennai');

    // Add Destination Marker
    L.marker(destCoords, {
      icon: L.divIcon({
        className: 'dest-marker',
        html: `<div style="background-color: #22c55e; width: 14px; height: 14px; border-radius: 50%; border: 3px solid white; box-shadow: 0 0 15px #22c55e;"></div>`,
        iconSize: [14, 14],
        iconAnchor: [7, 7]
      })
    }).addTo(markersLayerRef.current).bindPopup(`Destination: ${destinationName}`);

    // Draw all routes (faint)
    routes.forEach(route => {
      const isSelected = route.id === selectedId;
      const coords = roadGeometry[route.id] || activeCoords;

      const polyline = L.polyline(coords, {
        color: isSelected ? '#06b6d4' : '#333',
        weight: isSelected ? 6 : 3,
        opacity: isSelected ? 0.9 : 0.3,
        lineCap: 'round',
        lineJoin: 'round'
      }).addTo(routeLayersRef.current!);

      if (isSelected) {
        // Add Charging Stops Markers along the ACTUAL road path
        route.chargingStops?.forEach((stop) => {
          // Find approximate position on the coordinate array
          const stopRatio = Math.min(0.95, stop.kmAt / route.distanceKm);
          const stopIdx = Math.floor(stopRatio * (coords.length - 1));
          const stopCoords = coords[stopIdx];

          if (stopCoords) {
            L.marker(stopCoords, {
              icon: L.divIcon({
                className: 'charging-icon',
                html: `
                  <div style="background-color: #f97316; width: 28px; height: 28px; border-radius: 8px; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 20px rgba(249,115,22,0.8); border: 2px solid white;">
                    <svg style="width: 16px; height: 16px; color: white;" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                `,
                iconSize: [28, 28],
                iconAnchor: [14, 14]
              })
            }).addTo(markersLayerRef.current!).bindPopup(stop.label);
          }
        });

        // Fit map to bounds of the selected road route
        mapRef.current?.fitBounds(polyline.getBounds(), { padding: [60, 60] });
      }
    });

  }, [routes, selectedId, destinationName, roadGeometry]);

  return (
    <div className="relative w-full h-full glass-panel rounded-3xl overflow-hidden border border-white/5 shadow-2xl">
      <div ref={mapContainerRef} className="w-full h-full z-0" />

      {/* Route Selection Overlays */}
      <div className="absolute bottom-6 left-6 flex flex-col gap-2 z-[1000]">
        {routes.map(route => (
          <button
            key={route.id}
            onClick={() => onSelect(route.id)}
            className={`px-4 py-3 rounded-xl transition-all flex items-center gap-4 text-left ${
              selectedId === route.id ? 'bg-cyan-500/30 border border-cyan-500/50 backdrop-blur-md shadow-lg scale-105' : 'bg-black/80 border border-white/10 hover:bg-black/90'
            }`}
          >
            <div className="flex-1">
              <div className="text-[10px] font-black uppercase tracking-widest text-cyan-400 mb-0.5">{route.name}</div>
              <div className="text-xs font-bold text-white">
                {route.distanceKm}km • {route.durationMin}m
              </div>
            </div>
            {route.distanceKm > 100 && (
              <div className="bg-orange-500/20 text-orange-400 p-1 rounded-md border border-orange-500/30">
                <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
            )}
          </button>
        ))}
      </div>

      {/* Map Legend */}
      <div className="absolute top-6 right-6 p-3 bg-black/80 border border-white/10 rounded-xl backdrop-blur-md z-[1000] flex flex-col gap-2">
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-cyan-500 shadow-[0_0_5px_#06b6d4]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">VIT Chennai (Origin)</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-green-500 shadow-[0_0_5px_#22c55e]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">Road Destination</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded bg-orange-500 shadow-[0_0_5px_#f97316]"></div>
            <span className="text-[9px] font-bold text-gray-300 uppercase">EV Charge Point</span>
         </div>
         <div className="mt-1 pt-1 border-t border-white/10">
            <span className="text-[8px] text-gray-500 uppercase font-black">Powered by OSRM Road Logic</span>
         </div>
      </div>
    </div>
  );
};

export default MapOverlay;

import React, { useState, useEffect } from 'react';
import Speedometer from './components/Speedometer';
import MapOverlay from './components/MapOverlay';
import { RouteOption, EVState, ChargingStop } from './types';
import { optimizeRoute, getEfficiencyTip, EnhancedRouteOption } from './services/geminiService';

const MAX_VEHICLE_RANGE = 100;

const App: React.FC = () => {
  const [routes, setRoutes] = useState<EnhancedRouteOption[]>([]);
  const [selectedRouteId, setSelectedRouteId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isSimulated, setIsSimulated] = useState(false);
  const [destinationInput, setDestinationInput] = useState('Marina Beach');
  const [activeDestination, setActiveDestination] = useState('Marina Beach');
  const [efficiencyTip, setEfficiencyTip] = useState<string>('System Check: Road Routing Active');
  const [userLoc, setUserLoc] = useState<{ latitude: number, longitude: number } | undefined>();

  const [evState, setEvState] = useState<EVState>({
    currentSpeed: 0,
    recommendedSpeed: 80,
    batteryPercent: 100,
    rangeKm: MAX_VEHICLE_RANGE,
    maxRangeKm: MAX_VEHICLE_RANGE,
    efficiencyWhKm: 150,
    instantConsumptionKw: 0
  });

  const processRangeFeasibility = (rawRoutes: EnhancedRouteOption[]): EnhancedRouteOption[] => {
    return rawRoutes.map(route => {
      const stops: ChargingStop[] = [];
      if (route.distanceKm > MAX_VEHICLE_RANGE) {
        const numStops = Math.floor(route.distanceKm / MAX_VEHICLE_RANGE);
        for (let i = 1; i <= numStops; i++) {
          stops.push({
            id: `stop-${i}`,
            kmAt: i * MAX_VEHICLE_RANGE,
            label: `⚡ Charging Stop ${i} (${i * MAX_VEHICLE_RANGE}km)`
          });
        }
      }
      return { ...route, chargingStops: stops };
    });
  };

  const fetchRoutes = async (target: string, location?: { latitude: number, longitude: number }) => {
    setIsUpdating(true);
    try {
      const rawRoutes = await optimizeRoute(target, evState.batteryPercent, location);
      const routesWithStops = processRangeFeasibility(rawRoutes);

      setRoutes(routesWithStops);
      setIsSimulated(routesWithStops.some(r => r.isSimulated));

      const optimal = routesWithStops.find(r => r.isOptimal) || routesWithStops[0];
      setSelectedRouteId(optimal.id);
      setActiveDestination(target);
    } catch (error) {
      console.error("Critical Failure in Routing:", error);
    } finally {
      setIsUpdating(false);
      setLoading(false);
    }
  };

  const handleRefreshLocation = () => {
    fetchRoutes(activeDestination, { latitude: 12.8406, longitude: 80.1534 }); // Hard-coded VIT Origin
  };

  useEffect(() => {
    handleRefreshLocation();
  }, []);

  useEffect(() => {
    // Keeping speed at 0 for stationary vehicle
    const timer = setInterval(() => {
      setEvState(prev => ({
        ...prev,
        currentSpeed: 0,
        instantConsumptionKw: 0.2 + (Math.random() * 0.2), 
        rangeKm: Math.max(0, MAX_VEHICLE_RANGE * (prev.batteryPercent / 100))
      }));
    }, 1000);

    const tipTimer = setInterval(async () => {
      if (!isSimulated) {
        const tip = await getEfficiencyTip(evState.currentSpeed, evState.batteryPercent);
        setEfficiencyTip(tip);
      } else {
        setEfficiencyTip("Road-based optimal path calculation is running.");
      }
    }, 25000);

    return () => {
      clearInterval(timer);
      clearInterval(tipTimer);
    };
  }, [evState.currentSpeed, evState.batteryPercent, isSimulated]);

  const handleDestinationSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (destinationInput.trim()) {
      fetchRoutes(destinationInput.trim(), userLoc);
    }
  };

  const selectedRoute = routes.find(r => r.id === selectedRouteId);
  const needsRecharge = selectedRoute && selectedRoute.distanceKm > MAX_VEHICLE_RANGE;
  const numStops = selectedRoute?.chargingStops?.length || 0;
  const arrivalTime = selectedRoute ? new Date(Date.now() + selectedRoute.durationMin * 60000) : null;

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-black">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
          <div className="text-cyan-400 font-orbitron tracking-widest text-lg uppercase">Syncing Road Network...</div>
          <div className="text-gray-500 text-sm italic">Origin: VIT Chennai</div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-[#050505] p-4 gap-4 overflow-hidden">
      <header className="flex justify-between items-center px-6 py-3 glass-panel rounded-2xl h-20 shadow-xl border-b border-white/5">
        <div className="flex items-center gap-6">
          <div className="flex flex-col min-w-[100px]">
            <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Travel Time</span>
            <span className="text-lg font-orbitron text-cyan-400">
              {selectedRoute ? `${selectedRoute.durationMin} MINS` : '--'}
            </span>
          </div>
          <div className="h-10 w-[1px] bg-white/10"></div>

          <div className="flex items-center gap-3">
            <form onSubmit={handleDestinationSubmit} className="flex items-center gap-2">
              <div className="flex flex-col">
                <label className="text-[10px] text-gray-500 uppercase font-bold tracking-widest mb-0.5">Destination (From VIT)</label>
                <div className="relative">
                  <input 
                    type="text" 
                    value={destinationInput}
                    onChange={(e) => setDestinationInput(e.target.value)}
                    className="bg-black/40 border border-white/10 rounded-lg pl-3 pr-10 py-1.5 text-sm font-semibold focus:outline-none focus:border-cyan-500/50 transition-all w-48 md:w-80"
                  />
                  <button type="button" onClick={handleRefreshLocation} className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-cyan-400">
                    <svg className={`w-4 h-4 ${isUpdating ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                    </svg>
                  </button>
                </div>
              </div>
              <button type="submit" disabled={isUpdating} className="mt-4 p-2 bg-cyan-500/20 rounded-lg border border-cyan-500/30 hover:bg-cyan-500/30 transition-all">
                <svg className="w-4 h-4 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
              </button>
            </form>
          </div>
        </div>

        <div className="flex items-center gap-10">
           {isSimulated && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-yellow-500/10 border border-yellow-500/20 rounded-lg">
                <div className="w-2 h-2 rounded-full bg-yellow-500 animate-pulse"></div>
                <span className="text-[10px] font-black text-yellow-500 uppercase tracking-widest">Road Path Simulation</span>
              </div>
           )}

           {needsRecharge && (
             <div className="bg-orange-500/20 border border-orange-500/40 px-4 py-2 rounded-xl flex items-center gap-3 animate-pulse">
                <div className="p-1.5 bg-orange-500 rounded-lg">
                  <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-orange-400 uppercase tracking-tighter">Road Charging</span>
                  <span className="text-[11px] text-white font-bold leading-none">STOPS: {numStops}</span>
                </div>
             </div>
           )}

           <div className="flex flex-col items-end">
              <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">ETA</span>
              <span className="text-lg font-orbitron text-white">{arrivalTime?.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) || '--:--'}</span>
           </div>

           <div className="flex items-center gap-3">
              <div className="flex flex-col items-end">
                <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Battery</span>
                <span className="text-lg font-orbitron text-green-400">{evState.batteryPercent}%</span>
              </div>
              <div className="w-14 h-7 border border-white/20 rounded-md flex items-center p-0.5 relative">
                 <div className="h-full bg-green-500 shadow-[0_0_10px_#22c55e66] rounded-sm transition-all duration-1000" style={{ width: `${evState.batteryPercent}%` }} />
                 <div className="absolute -right-1.5 w-1.5 h-3.5 bg-white/30 rounded-r"></div>
              </div>
           </div>
        </div>
      </header>

      <main className="flex-1 grid grid-cols-12 gap-4 min-h-0">
        <div className="col-span-12 lg:col-span-8 flex flex-col gap-4">
          <div className="flex-1">
            <MapOverlay 
              routes={routes} 
              selectedId={selectedRouteId} 
              onSelect={setSelectedRouteId} 
              destinationName={activeDestination}
            />
          </div>

          <div className="glass-panel p-6 rounded-3xl grid grid-cols-4 gap-6 border border-white/5 shadow-xl">
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Road Distance</span>
                <span className={`text-xl font-orbitron ${needsRecharge ? 'text-orange-400' : 'text-cyan-400'}`}>
                  {selectedRoute?.distanceKm} km
                </span>
                <div className="flex items-center gap-1 mt-1 opacity-60">
                   <div className="w-1.5 h-1.5 rounded-full bg-cyan-500"></div>
                   <span className="text-[9px] text-gray-400 font-bold uppercase">Max Charge: {MAX_VEHICLE_RANGE}km</span>
                </div>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] text-gray-500 uppercase font-bold">Feasibility</span>
                <span className={`text-xs font-black mt-1 p-1 rounded-md text-center border ${needsRecharge ? 'text-orange-400 border-orange-500/30 bg-orange-500/5' : 'text-green-400 border-green-500/30 bg-green-500/5'}`}>
                  {needsRecharge ? "STOP REQUIRED" : "DIRECT ROAD"}
                </span>
              </div>
              <div className="flex flex-col col-span-2">
                <span className="text-[10px] text-gray-500 uppercase font-bold">OSRM Navigation Intelligence</span>
                <p className={`text-xs font-semibold leading-tight mt-1 ${needsRecharge ? 'text-orange-200' : 'text-cyan-100'}`}>
                  Route from VIT Chennai now follows actual mapped roads.
                  {needsRecharge && ` Automated stop(s) added along the network every 100km.`}
                </p>
                {isSimulated && (
                  <p className="text-[9px] text-yellow-500/80 mt-1 font-bold uppercase tracking-wider">
                    API Quota Limit: Switching to Road Heuristics + OSRM Open Engine.
                  </p>
                )}
              </div>
          </div>
        </div>

        <div className="col-span-12 lg:col-span-4 flex flex-col gap-4">
          <div className="flex-1">
            <Speedometer 
               currentSpeed={evState.currentSpeed} 
               recommendedSpeed={evState.recommendedSpeed}
               consumption={evState.instantConsumptionKw}
            />
          </div>
          <div className="glass-panel p-6 rounded-3xl border-l-4 border-l-cyan-500 shadow-lg">
             <div className="flex items-start gap-4">
                <div className="p-2 bg-cyan-500/20 rounded-xl">
                   <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                </div>
                <div className="flex-1">
                  <h3 className="text-[10px] text-gray-400 uppercase font-bold tracking-widest mb-1">Eco-Pilot Assistant</h3>
                  <p className="text-sm font-medium text-gray-200 italic leading-snug">"{efficiencyTip}"</p>
                </div>
             </div>
          </div>
        </div>
      </main>

      <footer className="h-10 flex items-center justify-between px-6 opacity-40">
         <div className="text-[9px] text-gray-500 uppercase tracking-widest font-black">
           MVP 1.0 • Road Network Mode • JESUS FAVICON
         </div>
         <div className="text-[9px] text-gray-500 uppercase tracking-widest font-bold">
           Stationary: 0 km/h
         </div>
      </footer>
    </div>
  );
